uantite":4,"quantite_min":null,"quantite_max":null,"provenance":"proposition_test"},{"id":"bf_flan_coco_ing4","nom":"Noix de coco râpée","unite":"g","quantite":80,"quantite_min":null,"quantite_max":null,"provenance":"proposition_test"},{"id":"bf_flan_coco_ing5","nom":"Sucre pour caramel","unite":"g","quantite":100,"quantite_min":null,"quantite_max":null,"notes":"Option selon présentation","provenance":"proposition_test"}],"etapes":["Préparer un caramel si cette présentation est choisie.","Mélanger œufs et laits sans excès de mousse, incorporer la noix de coco.","Verser dans un moule adapté et cuire au bain-marie en contrôlant la prise.","Refroidir sous contrôle et découper après essai de rendement."],"allergenes":["oeufs","lait"],"tags":["flan","coco","dessert","dessert_a_valider"],"notes":"[Origine : proposition_test · Offre : dessert_a_valider]\n\nÀ vérifier avant toute validation : Rendement et grammage réels · Température de cuisson/conservation applicable au produit · Hygiène et traçabilité des ingrédients · Étiquetage et allergènes définitifs\n\nRendement de référence (source) : 8 parts (essai) — rendement réel à mesurer"}]
  $import$::jsonb) as x(
    source text, nom text, categorie text, sous_cat text, nb_parts int,
    ingredients jsonb, etapes text[], allergenes text[], tags text[], notes text
  )
)
insert into public.food_recettes
  (nom, categorie, sous_cat, nb_parts, ingredients, etapes, allergenes, tags, statut, source, source_type, notes, date_import)
select d.nom, d.categorie, d.sous_cat, d.nb_parts, d.ingredients, d.etapes, d.allergenes, d.tags,
  'brouillon', d.source, 'import_fiches_bellafood', d.notes, current_date
from donnees d
where not exists (
  select 1 from public.food_recettes fr where fr.source = d.source
);

